using System;
using UnityEngine;
public static class CatalogMathValidation {
 static void Check(bool ok,string message){if(!ok)throw new Exception("SourceMath validation: "+message);}
 static void Near(float actual,float expected,string message){Check(Mathf.Abs(actual-expected)<.0001f,message+" actual="+actual);}
 public static void Run(){
  var sine=new SourceMathBinding("sine");Near(sine.Evaluate(Mathf.PI/4),1,"printed sin(2x) at pi/4");Near(sine.Period,Mathf.PI,"printed sine period");sine.Axes(Vector2.zero,new Vector2(1,0),1);Near(sine.frequency,4,"right stick changes coefficient");sine.Reset();sine.Axes(new Vector2(1,0),Vector2.zero,1);Near(sine.frequency,2*Mathf.PI/(Mathf.PI+1),"left graph-period control inverse-binds frequency");sine.SetFrequency(float.NaN);Check(!float.IsNaN(sine.frequency),"nonfinite input rejected");
  var sum=new SourceMathBinding("summation");Check(sum.Total==210&&sum.Terms.Length==20,"printed1through20 sum210");sum.Axes(Vector2.zero,new Vector2(0,1),.2f);Check(sum.Upper==22&&sum.Total==253,"upper controller updates expansion/total");sum.SetLower(100);sum.SetUpper(0);Check(sum.Terms.Length==0&&sum.Total==0,"reversed bounds empty, not invalid range");
  var triangle=new SourceMathBinding("triangle");Near(triangle.b,132f/212f,"source contour normalized leg");triangle.SetA(1);triangle.SetB(1);Near(triangle.C,Mathf.Sqrt(2),"Pythagorean diagonal");triangle.SetA(2);triangle.SetAngle(45);Near(triangle.b,2,"angle/leg coupling");Near(triangle.Angle,45,"bidirectional angle");
  // Exercise actual scene adapter and the same ControlAxes dispatch used by OVRInput.
  foreach(string mode in new[]{"sine","summation","triangle"}){
   var go=new GameObject("SourceMath integration check "+mode);var scene=go.AddComponent<CatalogScene>();scene.Configure(new CatalogItem{id="original-math-"+mode,title=mode,animation="math-"+mode,width=.21f,height=.12f});var adapter=go.GetComponent<SourceMathScene>();Check(adapter!=null&&adapter.spec.referenceCrop.Length==4,"prepared source spec loaded");string before=adapter.binding.Equation;scene.ControlAxes(new Vector2(.5f,.5f),new Vector2(.5f,.5f),.5f,"editor-synthetic");adapter.Render();Check(before!=adapter.binding.Equation,"actual axis dispatch changes "+mode+" state");if(mode!="summation")Check(go.GetComponentsInChildren<LineRenderer>()[0].positionCount>0,"source figure geometry populated");scene.Reset();Check(adapter.binding.selected,"reset restores selected relationship");UnityEngine.Object.DestroyImmediate(go);
  }
  var catalog=JsonUtility.FromJson<CatalogManifest>(Resources.Load<TextAsset>("Catalog/manifest").text);var carItem=Array.Find(catalog.items,x=>x.id=="original-oct2-printed-car");var carGo=new GameObject("Actual reference-car kinematics fixture");var car=carGo.AddComponent<CatalogScene>();car.Configure(carItem);var body=carGo.transform.Find("Inferred mesh (unrigged)");Check(body.GetComponent<MeshFilter>().sharedMesh.vertexCount>1000,"actual inferred car mesh loaded");Check(carGo.GetComponentsInChildren<MeshFilter>().Length==1,"no coloured wheel stand-ins");var update=typeof(CatalogScene).GetMethod("Update",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);car.time=0;update.Invoke(car,null);Vector3 first=body.localPosition;car.time=1;update.Invoke(car,null);Check(Vector3.Distance(first,body.localPosition)>.01f,"actual inferred rigid body translates, not markers only");car.ControlAxes(Vector2.zero,new Vector2(1,0),.5f,"editor-synthetic");update.Invoke(car,null);Check(Quaternion.Angle(Quaternion.identity,body.localRotation)>5,"controller parameter steers actual body");UnityEngine.Object.DestroyImmediate(carGo);
  Debug.Log("CATALOG RIGID CAR VALIDATION PASSED: actual inferred body translation/steering; no coloured wheel stand-ins; editor-synthetic, not physical inputs.");
  Debug.Log("CATALOG SOURCE MATH VALIDATION PASSED: mathematical goldens, nonfinite/bounds handling, actual scene axis dispatch, source specs and curve/leg geometry; not physical inputs.");
 }
}
